/* teste do desafio medidor-de-palavras — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece DENTRO do teste: freopen manda o stdout
   para o arquivo temporario, o teste chama a funcao do aluno e le o
   arquivo de volta (fflush, nunca fclose no stdout). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void medidorDePalavras(void);

SM_TEST(as_tres_medidas_na_ordem) {
    freopen("sm_saida.tmp", "w", stdout);
    medidorDePalavras();
    fflush(stdout);

    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a medida de sol", linha, "sol tem 3 letras\n",
              "sol tem tres letras, e o terminador nao entra na conta");
    fgets(linha, 80, f);
    checa_str("a medida de computador", linha, "computador tem 10 letras\n",
              "computador tem dez letras: o strlen para na placa do fim");
    fgets(linha, 80, f);
    checa_str("a medida de paralelepipedo", linha, "paralelepipedo tem 14 letras\n",
              "paralelepipedo tem quatorze letras, contadas pelo strlen");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
