#include <stdio.h>
#include <string.h>

void medidorDePalavras(void) {
    char primeira[] = "sol";
    char segunda[] = "computador";
    char terceira[] = "paralelepipedo";
    int a = strlen(primeira);
    int b = strlen(segunda);
    int c = strlen(terceira);
    printf("%s tem %d letras\n", primeira, a);
    printf("%s tem %d letras\n", segunda, b);
    printf("%s tem %d letras\n", terceira, c);
}
